import data from '../data/confusables.json';

/** Latin/Cyrillic/Greek → Latin subset of Unicode confusables.txt (generated by `npm run build:data`). */
export const confusables: Readonly<Record<string, string>> = data;

/**
 * Confusables skeleton (UTS #39 style, restricted to the bundled subset):
 * lowercase + NFD, map each code point, NFD again. Two labels that look alike
 * (`tudеlft` with Cyrillic е vs `tudelft`) get the same skeleton.
 */
export function skeleton(label: string): string {
  let out = '';
  for (const ch of label.toLowerCase().normalize('NFD')) out += confusables[ch] ?? ch;
  return out.normalize('NFD');
}
